'use client'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { motion } from 'framer-motion'

const LINKS = [
  { href: '/atlas',    label: 'Atlas'    },
  { href: '/comparar', label: 'Comparar' },
  { href: '/reportes', label: 'Reportes' },
  { href: '/foro',     label: 'Foro'     },
]

export default function TopNav() {
  const path = usePathname()

  return (
    <motion.nav
      initial={{ y: -46, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}
      style={{
        height: 46,
        background: 'var(--bg-2)',
        borderBottom: '1px solid var(--line-2)',
        display: 'flex',
        alignItems: 'center',
        padding: '0 20px',
        flexShrink: 0,
        position: 'relative',
        zIndex: 10,
      }}
    >
      {/* Gradient bottom line */}
      <div style={{
        position: 'absolute', bottom: -1, left: 0, right: 0, height: 1,
        background: 'linear-gradient(90deg, var(--accent), transparent 60%)',
        opacity: 0.5, pointerEvents: 'none',
      }} />

      {/* Logo */}
      <Link href="/atlas" style={{ textDecoration: 'none', marginRight: 18, flexShrink: 0 }}>
        <span style={{ fontFamily: 'var(--serif)', fontWeight: 900, fontSize: 20, letterSpacing: '-0.02em', color: 'var(--text)' }}>
          Aletheia{' '}
          <em style={{ fontStyle: 'italic', fontWeight: 300, fontSize: '0.72em', color: 'var(--accent)' }}>IEA</em>
        </span>
      </Link>

      {/* Separator + sub */}
      <span style={{
        fontFamily: 'var(--mono)', fontSize: 8, letterSpacing: '0.14em', textTransform: 'uppercase',
        color: 'var(--text-3)', borderLeft: '1px solid var(--line-2)', paddingLeft: 14, marginRight: 20, whiteSpace: 'nowrap',
      }}>
        Integridad Institucional · A. Latina
      </span>

      {/* Nav links */}
      <div style={{ display: 'flex', alignItems: 'center' }}>
        {LINKS.map(({ href, label }) => {
          const active = path.startsWith(href)
          return (
            <Link
              key={href}
              href={href}
              style={{
                fontFamily: 'var(--mono)', fontSize: 9, letterSpacing: '0.1em', textTransform: 'uppercase',
                color: active ? 'var(--accent)' : 'var(--text-3)',
                textDecoration: 'none',
                padding: '0 14px', height: 46,
                display: 'flex', alignItems: 'center',
                borderBottom: `2px solid ${active ? 'var(--accent)' : 'transparent'}`,
                transition: 'color .15s, border-color .15s',
              }}
              onMouseEnter={e => { if (!active) (e.currentTarget as HTMLElement).style.color = 'var(--text-2)' }}
              onMouseLeave={e => { if (!active) (e.currentTarget as HTMLElement).style.color = 'var(--text-3)' }}
            >
              {label}
            </Link>
          )
        })}
      </div>

      {/* Right */}
      <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 12 }}>
        <span style={{
          fontFamily: 'var(--mono)', fontSize: 11, color: 'var(--accent)',
          background: 'rgba(56,189,248,.08)', border: '1px solid rgba(56,189,248,.2)',
          padding: '3px 10px',
        }}>
          2023
        </span>
        <div style={{ width: 1, height: 16, background: 'var(--line-2)' }} />
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <div style={{
            width: 6, height: 6, borderRadius: '50%',
            background: 'var(--good)', animation: 'pulse 2s ease-in-out infinite',
          }} />
          <span style={{ fontFamily: 'var(--mono)', fontSize: 8, letterSpacing: '0.15em', textTransform: 'uppercase', color: 'var(--good)' }}>
            Live
          </span>
        </div>
      </div>
    </motion.nav>
  )
}
